


export type ExpandedShipmentSummary = { /** RFC3339 timestamp. Format: date-time. */ "created_at"?: string; /** RFC3339 timestamp. Format: date-time. */ "delivered_at"?: string; "direction": "outbound" | "return" | (string & {}); "fulfillment_id": string; /** RFC3339 timestamp. Format: date-time. */ "handed_off_at"?: string; /** Total number of packages attached to the shipment, including voided packages. Format: int32. minimum: 0. */ "package_count": number; "shipment_id": string; /** RFC3339 timestamp. Format: date-time. */ "shipped_at"?: string; /** Read-only shipment state. - `created`: The shipment leg exists but has not been packed or handed off. - `packed`: The shipment leg is packed and awaiting carrier handoff. - `shipped`: The shipment leg was handed to the carrier. - `in_transit`: The carrier is moving the shipment through its network. - `out_for_delivery`: The shipment is on its final delivery route. - `delivered`: The carrier reported successful delivery. - `delivery_attempted`: The carrier attempted delivery but did not complete it. Follow the carrier instructions before retrying delivery. - `exception`: A carrier exception is blocking normal progress. Resolve the carrier-reported issue. - `returned`: The shipment was returned toward or to its origin. - `voided`: The shipment was voided and will not continue through delivery. */ "status": "created" | "packed" | "shipped" | "in_transit" | "out_for_delivery" | "delivered" | "delivery_attempted" | "exception" | "returned" | "voided" | (string & {}); /** RFC3339 timestamp. Format: date-time. */ "updated_at"?: string; };
